import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const hash=(v,alg='sha256')=>createHash(alg).update(v).digest('hex');
const raw=p=>readFileSync(p), load=p=>JSON.parse(raw(p));
const sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;
const canon=v=>hash(JSON.stringify(sort(v)));
const base='tests/fixtures/notice-license-facts-v3', r=base+'/revisions/source-binding-r2';
const receiptPath='tmp/luna-r2-review-20261012-223546.json', receipt=load(receiptPath);
const manifest=load(r+'/manifest.json'), amend=load(r+'/amendment.json'), current=load(r+'/facts.json'), old=load(base+'/facts.json');
const git=args=>execFileSync('git',args,{encoding:null,timeout:20000,maxBuffer:16777216,env:{...process.env,GIT_NO_LAZY_FETCH:'1',GIT_NO_REPLACE_OBJECTS:'1'}});
const checks=[]; const check=(name,condition)=>{checks.push({name,status:condition?'PASS':'FAIL'});if(!condition)throw Error(name);};
check('entry receipt fresh independent run and zero failures',receipt.generated_at>'2026-10-12T14:35:00Z'&&receipt.receipt_checks.pass===221&&receipt.receipt_checks.fail===0&&receipt.commands.every(c=>c.exit_code===0));
check('single fixed commit across all 15 unique source paths',manifest.source_commit==='9d67b88f39fa4aaa8ab24048aea224204eabd490'&&manifest.sources.length===15&&new Set(manifest.sources.map(s=>s.path)).size===15&&manifest.sources.every(s=>s.source_commit===manifest.source_commit));
const blobs=[];const sourceBytes=new Map();
for(const s of manifest.sources){
 const tree=git(['ls-tree','-z',manifest.source_commit,'--',s.path]).toString('utf8');
 const m=/^100644 blob ([a-f0-9]{40})\t([^\x00]+)\x00$/.exec(tree);
 if(!m||m[2]!==s.path)throw Error('not exact regular blob');
 const b=git(['cat-file','blob',m[1]]);
 const objectHash=hash(Buffer.concat([Buffer.from(`blob ${b.length}\0`),b]),'sha1');
 check('Git object identity and raw bytes: '+s.path,objectHash===m[1]&&b.length===s.size_bytes&&hash(b)===s.sha256);
 sourceBytes.set(s.path,b);blobs.push({path:s.path,git_blob_oid:m[1],mode:'100644',size_bytes:b.length,sha256:hash(b)});
}
check('manifest listed artifacts exact size and raw hashes',manifest.artifacts.every(a=>raw(r+'/'+a.path).length===a.size_bytes&&hash(raw(r+'/'+a.path))===a.sha256));
check('31 unique facts and 31 unique evidence',current.facts.length===31&&current.evidence.length===31&&new Set(current.facts.map(f=>f.fact_id)).size===31&&new Set(current.evidence.map(e=>e.evidence_id)).size===31);
check('five source inputs use same pinned raw blobs and revision',current.source_inputs.length===5&&current.source_inputs.every(s=>sourceBytes.has(s.path)&&hash(sourceBytes.get(s.path))===s.source_file_sha256&&s.source_revision===manifest.source_commit));
check('all evidence source files close over fixed blob bytes',current.evidence.every(e=>sourceBytes.has(e.source_path)&&hash(sourceBytes.get(e.source_path))===e.source_file_sha256));
const changes=current.evidence.filter(e=>old.evidence.find(p=>p.evidence_id===e.evidence_id).source_file_sha256!==e.source_file_sha256);
check('all eight amendment entries exactly bind old new selected fields',changes.length===8&&amend.affected_evidence.length===8&&new Set(amend.affected_evidence.map(e=>e.evidence_id)).size===8&&changes.every(e=>{const a=amend.affected_evidence.find(a=>a.evidence_id===e.evidence_id),p=old.evidence.find(p=>p.evidence_id===e.evidence_id);return a&&a.source_path===e.source_path&&a.source_revision===manifest.source_commit&&a.previous_source_file_sha256===p.source_file_sha256&&a.corrected_source_file_sha256===e.source_file_sha256&&a.selected_content_sha256===e.selected_content_sha256&&e.source_path==='frontend/package.json';}));
const packageBlob=JSON.parse(sourceBytes.get('frontend/package.json'));
check('eight npm selections independently resolve RFC6901 pointer strings',changes.every(e=>{const selected=e.selected_json_pointer.split('/').slice(1).reduce((o,t)=>o[t.replaceAll('~1','/').replaceAll('~0','~')],packageBlob);return typeof selected==='string'&&hash(selected)===e.selected_content_sha256;}));
check('all selected hashes unchanged and fact report semantics unchanged',current.evidence.every(e=>old.evidence.find(p=>p.evidence_id===e.evidence_id).selected_content_sha256===e.selected_content_sha256)&&canon(old.facts)===canon(current.facts)&&canon(old.report_v3_rows)===canon(current.report_v3_rows));
check('parent and replacement raw canonical pins distinguish formats',hash(raw(base+'/facts.json'))===amend.parent.file_sha256&&canon(old)===amend.parent.canonical_package_sha256&&hash(raw(r+'/facts.json'))===amend.replacement.file_sha256&&canon(current)===amend.replacement.canonical_package_sha256&&amend.replacement.file_sha256!==amend.replacement.canonical_package_sha256);
check('observation remains draft pending unlicensed expression',current.package_status==='draft_facts_only'&&current.facts.every(f=>f.authorization_status==='pending'&&f.license_expression_id===null));
check('original approval and A binding fields remain null',amend.independent_review===null&&amend.human_approval===null&&amend.a_terminal_readback===null&&manifest.independent_review===null&&manifest.a_terminal_readback===null);
const pinPaths=[r+'/facts.json',r+'/manifest.json',r+'/amendment.json',base+'/facts.json',base+'/generate.mjs',base+'/fixed-git-source.mjs','docs/p1/p1-b-evidence-followup-20261012.mjs','docs/p1/p1-b-evidence-followup-20261012.json','docs/p1/p1-b-validation-20261012.json','docs/p1/p1-b-offline-audit-20261011.json','backend/app/detectors/license_notice_facts_v3_adapter.py','backend/app/p1/notice_source_adapter.py'];
const pins=pinPaths.map(path=>({path,size_bytes:raw(path).length,sha256:hash(raw(path))}));
check('entry script pin agrees with independently executed receipt',pins.find(p=>p.path===receipt.verification_entry.path).sha256===receipt.verification_entry.sha256);
